
from pathlib import Path
import json

import numpy as np
from sentence_transformers import SentenceTransformer


# Configuration
CHUNKS_FILE = Path("documents/document_chunks.json")
MODEL_NAME = "sentence-transformers/all-MiniLM-L6-v2"
TOP_K = 3


def load_chunks(file_path):
    """Load chunks generated by our text chunker."""
    if not file_path.is_file():
        raise FileNotFoundError(
            f"Chunks file not found: {file_path}. "
            "Run text_chunker.py first."
        )

    chunks = json.loads(file_path.read_text(encoding="utf-8"))

    if not chunks:
        raise ValueError("The chunks file is empty.")

    return chunks


def create_embeddings(texts, model):
    """Convert a list of texts into normalized vectors."""
    embeddings = model.encode(
        texts,
        convert_to_numpy=True,
        normalize_embeddings=True,
    )

    return embeddings


def retrieve(query, model, chunks, chunk_embeddings, top_k=TOP_K):
    """Find the chunks most semantically similar to the query."""
    query_embedding = model.encode(
        [query],
        convert_to_numpy=True,
        normalize_embeddings=True,
    )[0]

    # Normalized vectors allow cosine similarity to be
    # calculated using the dot product.
    scores = chunk_embeddings @ query_embedding

    # Return the indices of the highest-scoring chunks.
    top_indices = np.argsort(scores)[::-1][:min(top_k, len(chunks))]

    results = []

    for index in top_indices:
        results.append({
            "chunk_id": chunks[index]["chunk_id"],
            "source_file": chunks[index]["source_file"],
            "score": float(scores[index]),
            "text": chunks[index]["text"],
        })

    return results


def main():
    chunks = load_chunks(CHUNKS_FILE)

    print(f"Loaded {len(chunks)} chunks.")
    print(f"Loading embedding model: {MODEL_NAME}")

    # The model may download its files the first time it runs.
    model = SentenceTransformer(MODEL_NAME)

    # Embed each document chunk once for this session.
    texts = [chunk["text"] for chunk in chunks]
    chunk_embeddings = create_embeddings(texts, model)

    print(f"Embedding matrix shape: {chunk_embeddings.shape}")
    print("\nSemantic search is ready!")
    print("Type a question, or type 'exit' to quit.\n")

    while True:
        query = input("Your question: ").strip()

        if query.lower() in {"exit", "quit"}:
            break

        if not query:
            continue

        results = retrieve(
            query,
            model,
            chunks,
            chunk_embeddings,
        )

        print("\n========== RETRIEVED CHUNKS ==========")

        for rank, result in enumerate(results, start=1):
            print(f"\nRank: {rank}")
            print(f"Chunk ID: {result['chunk_id']}")
            print(f"Similarity score: {result['score']:.4f}")
            print(f"Source: {result['source_file']}")
            print(f"Text:\n{result['text']}")

        print("\n" + "=" * 40 + "\n")


if __name__ == "__main__":
    main()
